const PORT := 7777
var peer: ENetMultiplayerPeer

func _ready():
	$Layout/ConnectionRow/HostBtn.pressed.connect(_on_host)
	$Layout/ConnectionRow/JoinBtn.pressed.connect(_on_join)
	$Layout/ChatRow/SendBtn.pressed.connect(_on_send)
	$Layout/StartGameBtn.pressed.connect(_on_start)
	multiplayer.peer_connected.connect(_on_player_connected)
	multiplayer.peer_disconnected.connect(_on_player_disconnected)

func _on_host():
	peer = ENetMultiplayerPeer.new()
	peer.create_server(PORT)
	multiplayer.multiplayer_peer = peer
	add_player(1)

func _on_join():
	var ip := $Layout/ConnectionRow/IPInput.text
	peer = ENetMultiplayerPeer.new()
	peer.create_client(ip, PORT)
	multiplayer.multiplayer_peer = peer

func _on_player_connected(id: int):
	add_player(id)

func _on_player_disconnected(id: int):
	remove_player(id)

func add_player(id: int):
	$Layout/PlayerList.add_item("Player " + str(id))

func remove_player(id: int):
	for i in range($Layout/PlayerList.item_count):
		if $Layout/PlayerList.get_item_text(i) == "Player " + str(id):
			$Layout/PlayerList.remove_item(i)
			break

func _on_send():
	var msg := $Layout/ChatRow/ChatInput.text
	if msg:
		send_chat.rpc(msg)
		$Layout/ChatRow/ChatInput.text = ""

@rpc("any_peer", "call_local")
func send_chat(msg: String):
	$Layout/ChatBox.add_text("Player: " + msg + "\n")

func _on_start():
	if multiplayer.is_server():
		print("Starting game...")"}}]}}

